 try{
  const key="numi-club-topup-return-v1";
  const context=JSON.parse(sessionStorage.getItem(key)||"null");
  sessionStorage.removeItem(key);
  if(context&&String(context.accountId)===String(account.id)&&Number(context.expires)>Date.now()){
   const path=String(context.path||"");
   if(/^\/(?!\/)[a-zA-Z0-9_/.\-]*$/.test(path)&&!path.includes("..")&&path!=="/wallet-topup.html"){
